// complete resumable-video API before any batch work starts, even for a static
// batch: a missing action is a deployment mismatch, not a media error.
const requiredVideoActions = [
  'start_video_upload',
  'transfer_video_chunk',
  'finish_video_upload',
  'get_video_status',
